export function referencePage(concept: Concept, locale: Locale, css: string): string {
  const t = referenceCopy[locale];
  const products = referenceProducts(locale);
  const price = (i: number) => products[i % 6].price.display;
  const image = (portrait = false) => `<img src="/sample.svg" alt="${portrait ? 'Alex Example' : t.product}" width="${portrait ? 440 : 800}" height="${portrait ? 484 : 450}">`;
  const action = (i: number) => `<a class="textlink small" href="/${locale}/p/example-${i}">${t.view}</a>`;
  const head = (heading: string) => `<div class="section-head"><div><p class="eyebrow">${t.eyebrow}</p><h2>${heading}</h2></div><p>${t.requirement}</p></div>`;
  const card = (i: number) => `<article class="product"><div class="cover">${image()}<span class="tag">${t.format}</span></div><div class="product-body"><p class="small blue">${i === 0 ? t.free : t.product}</p><h3>${t.tasks[i % 4]}</h3><p class="outcome">${t.result}</p><p class="metadata">${t.format}<br>${t.requires}</p><div class="buyrow"><span class="price">${price(i)}</span>${action(i)}</div><details class="detail"><summary>${t.details}</summary><div class="detail-body"><strong>${t.tasks[i % 4]}</strong><p>${t.receive}</p><strong>${t.requires}</strong><p>${t.requirement}</p><a class="button" href="/${locale}/checkout/example-${i}">${t.action} · ${price(i)}</a></div></details></div></article>`;
  const cards = (count: number) => `<div class="grid">${Array.from({ length: count }, (_, i) => card(i + (concept === 'c' ? 1 : 0))).join('')}</div>`;
  const taskLinks = `<div class="tasks">${t.tasks.map((task, i) => `<a class="task" href="#catalogue"><span class="num">0${i + 1}</span><h2>${task} ↗</h2><p>${t.taskBody}</p></a>`).join('')}</div>`;
  const search = `<label class="search"><svg aria-hidden="true" viewBox="0 0 24 24"><circle cx="10" cy="10" r="6.5"/><path d="m15 15 6 6"/></svg><input aria-label="${t.search}" placeholder="${t.search}"></label>`;
  const aHero = `<section class="hero wrap" data-crop="hero"><div class="hero-top"><div><p class="eyebrow">${t.eyebrow}</p><h1>${t.offer}</h1><p class="lead">${t.intro}</p><div class="offer-price"><span class="price">${price(1)}<small>${t.format}</small></span><a class="button" href="/${locale}/p/example-1">${t.action} ↗</a></div><p class="hero-note">${t.requirement}</p></div><div class="hero-visual"><div class="hero-cover">${image()}<div class="visual-caption"><span>${t.product}</span><span>PL / EN</span></div></div><div class="slot"><strong>${t.demo}</strong>${t.projectBody}</div></div></div><div class="what">${t.tasks.slice(0, 3).map((task, i) => `<div><strong>0${i + 1} / ${task}</strong><p>${t.receive}</p></div>`).join('')}</div></section><div class="ribbon"><div class="wrap">${t.tasks.map(task => `<a href="#catalogue">${task}</a>`).join('')}</div></div>`;
  const aComparison = `<section class="section comparison" data-crop="comparison"><div class="wrap"><p class="eyebrow">${t.distinct}</p><h2>${t.comparison}</h2><p class="lead">${t.distinct}</p><div class="compare-grid">${[0, 1].map(i => `<article class="compare-panel"><span class="tag">${i === 0 ? t.free : t.product}</span><h3>${t.tasks[i]}</h3><p class="lead">${t.result}</p><ul>${t.tasks.slice(0, 3).map(task => `<li>${task}</li>`).join('')}</ul><div class="buyrow"><span class="price">${price(i)}</span>${action(i)}</div></article>`).join('')}</div></div></section>`;
  const bHero = `<section class="hero wrap" data-crop="hero"><div class="hero-title"><div><p class="eyebrow">${t.eyebrow}</p><h1>${t.finder}</h1></div><p>${t.finderBody}</p></div>${search}${taskLinks}</section>`;
  const cHero = `<section class="hero wrap" data-crop="hero"><div class="hero-grid"><div><p class="eyebrow">${t.author}</p><h1>${t.authorTitle}</h1><p class="lead">${t.authorIntro}</p><div class="actions"><a class="button" href="#paths">${t.paths}</a><a class="textlink small" href="#catalogue">${t.catalogue}</a></div><p class="author-note">${t.note}</p></div><figure class="portrait">${image(true)}<figcaption><strong>Alex Example</strong><small>${t.note}</small></figcaption></figure></div></section>`;
  const story = `<section class="wrap editorial" data-crop="story"><h2>${t.story}</h2><div><blockquote>${t.quote}</blockquote><p>${t.authorIntro}</p></div></section>`;
  const paths = `<section id="paths" class="section paths wrap" data-crop="paths">${head(t.pathsTitle)}${t.tasks.map((task, i) => `<article class="path"><span class="path-num">0${i + 1}</span><div><h3>${task}</h3><p>${t.result}</p></div><div class="path-product">${image()}<div><span class="tag">${t.format}</span><h4>${task}</h4><div class="buyrow"><span class="price">${price(i)}</span>${action(i)}</div></div></div></article>`).join('')}</section>`;
  const projects = `<section class="section practice" data-crop="projects"><div class="wrap">${head(t.projects)}<div class="practice-grid">${[1, 2, 3].map(i => `<article class="practice-item"><h3>Example ${i} ↗</h3><p>${t.projectBody}</p><a class="textlink" href="https://example.test/project-${i}">${t.view}</a><div class="slot">${t.demo}</div></article>`).join('')}</div></div></section>`;
  const curated = `<section class="${concept === 'b' ? 'featured' : 'section curated'} wrap" data-crop="cards">${head(concept === 'b' ? t.featured : concept === 'c' ? t.paid : t.start)}${cards(concept === 'b' ? 6 : 3)}</section>`;
  const catalogue = `<section id="catalogue" class="section catalogue" data-crop="catalogue"><div class="wrap">${head(t.catalogueTitle)}${search}<div class="filters">${t.filters.map((filter, i) => `<button class="filter ${i === 0 ? 'active' : ''}">${filter}</button>`).join('')}<select aria-label="${t.categories}"><option>${t.categories}</option></select><select aria-label="${t.prices}"><option>${t.prices}</option></select></div><p class="results">${t.count}</p><div class="catalog-list">${Array.from({ length: 12 }, (_, i) => `<article class="catalog-item">${image()}<div><h3>${t.tasks[i % 4]}</h3><p>${t.format} · ${t.requires}</p></div><span class="price">${price(i)}</span></article>`).join('')}</div><div class="catalog-more"><button class="button secondary">${t.more}</button></div></div></section>`;
  const starter = `<section class="starter wrap" data-crop="starter"><div><h2>${t.starter}</h2><p>${t.result}</p></div><div class="actions"><a class="button" href="/${locale}/p/example-0">${t.view} · ${price(0)}</a></div></section>`;
  const faq = `<section class="section" data-crop="faq"><div class="wrap faq-layout"><h2>${t.faq}</h2><div class="faq">${[0, 1, 2].map(() => `<details><summary>${t.question}</summary><p>${t.answer}</p></details>`).join('')}</div></div></section>`;
  const closing = `<section class="closing" data-crop="closing"><div class="wrap"><h2>${t.closing}</h2><div class="actions"><a class="button" href="#catalogue">${t.browse}</a></div></div></section>`;
  return `<!doctype html><html lang="${locale}"><head><meta charset="utf-8"><title>Synthetic ${concept.toUpperCase()} reference</title><style>${css}</style></head><body class="${concept}"><div class="top"><header class="wrap"><a class="brand" href="#">${t.brand}<small>${t.sub}</small></a><nav><a href="#catalogue">${t.catalogue}</a><a class="desktop" href="#paths">${t.paths}</a><a class="account" href="/${locale}/my-products">${t.account}</a></nav></header></div><main>${concept === 'a' ? aHero + aComparison + curated : concept === 'b' ? bHero + curated : cHero + story + paths + projects + curated}${catalogue}${concept === 'b' ? starter : ''}${faq}${closing}</main><footer><div class="wrap"><div class="footer-row"><a class="brand" href="#">${t.brand}</a><div class="footer-links"><a href="/${locale}/terms">${t.terms}</a><a href="/${locale}/privacy">${t.privacy}</a></div></div><div class="footer-end"><span>© Example Studio · Synthetic reference</span><span>Sellf ↗</span></div></div></footer><aside class="cookie" hidden><div><h2>${t.cookie}</h2><p>${t.cookieBody}</p></div><div class="cookie-buttons"><button>${t.reject}</button><button>${t.accept}</button><button class="preferences">${t.customize}</button></div></aside></body></html>`;
}

/** Matching public DTOs for downstream renderer comparisons with these exact facts. */
export function referenceProducts(locale: Locale): PublicProductInfo[] {
  const t = referenceCopy[locale];
  return Array.from({ length: 6 }, (_, i) => ({
    id: `00000000-0000-4000-8000-${String(i + 1).padStart(12, '0')}`, slug: `example-${i}`, title: t.tasks[i % 4],
    price: { kind: i === 0 ? 'free' : 'one-time', display: locale === 'pl' ? `${i === 0 ? '0' : '49'} zł` : i === 0 ? 'PLN 0' : 'PLN 49', taxNote: null, omnibus: null },
    marketing: { format: 'template', sourceLocale: 'en', en: { result: referenceCopy.en.result, tools: [], requirements: [referenceCopy.en.requirement] }, pl: { result: referenceCopy.pl.result, tools: [], requirements: [referenceCopy.pl.requirement] } },
    image: { src: 'http://phase2.test/sample.svg', alt: t.product, width: 800, height: 450 },
    actions: { details: `/${locale}/p/example-${i}`, buy: `/${locale}/checkout/example-${i}` }, availability: 'available',
  }));
}

export function referenceCategories(locale: Locale): PublicCategoryInfo[] {
  return referenceCopy[locale].tasks.map((label, i) => ({ id: referenceProducts(locale)[i].id, label, filterTarget: 'catalogue' }));
}
